import io
import pickle
import hmac
import hashlib
import time
import json
import os
import re
from http.server import HTTPServer, BaseHTTPRequestHandler

SECRET_KEY = os.urandom(32)
ALLOWED_MODULES = ('builtins', 'datetime', 'collections', 'decimal')
ALLOWED_CLASSES = {
    'builtins': ('dict', 'list', 'tuple', 'set', 'frozenset', 'str', 'int', 'float', 'bool', 'bytes', 'NoneType'),
    'datetime': ('datetime', 'date', 'time', 'timedelta', 'timezone'),
    'collections': ('OrderedDict', 'defaultdict', 'deque'),
    'decimal': ('Decimal',),
}


class RestrictedUnpickler(pickle.Unpickler):
    """Safe unpickler that only allows whitelisted modules and classes.

    Security: Only permits deserialization of basic data types from
    pre-approved modules. Blocks arbitrary code execution by restricting
    find_class to known-safe combinations.
    """

    def find_class(self, module, name):
        # Validate module is exactly in our allowed list
        if module in ALLOWED_MODULES:
            # Validate class name within the module
            if name in ALLOWED_CLASSES.get(module, ()):
                return super().find_class(module, name)
        raise pickle.UnpicklingError(
            f"Restricted: {module}.{name} is not allowed"
        )


def compute_mac(data: bytes) -> str:
    """Compute HMAC-SHA256 for integrity verification."""
    return hmac.new(SECRET_KEY, data, hashlib.sha256).hexdigest()


def verify_mac(data: bytes, mac: str) -> bool:
    """Verify HMAC with constant-time comparison."""
    expected = compute_mac(data)
    return hmac.compare_digest(expected, mac)


def safe_deserialize(payload: bytes) -> object:
    """Deserialize a pickle payload using restricted unpickler.

    This function uses RestrictedUnpickler to ensure only safe
    types can be deserialized. Combined with HMAC verification
    at the transport layer, this provides defense-in-depth.
    """
    unpickler = RestrictedUnpickler(io.BytesIO(payload))
    unpickler.encoding = 'ASCII'
    return unpickler.load()


def safe_serialize(obj: object) -> bytes:
    """Serialize an object using pickle protocol 4."""
    return pickle.dumps(obj, protocol=4)


class SessionStore:
    """Server-side session storage with serialized state."""

    def __init__(self):
        self._sessions = {}

    def create_session(self, user_id: str, data: dict) -> str:
        """Create a new session with serialized data."""
        session_id = hashlib.sha256(
            f"{user_id}:{time.time()}:{os.urandom(16).hex()}".encode()
        ).hexdigest()[:32]

        serialized = safe_serialize(data)
        mac = compute_mac(serialized)

        self._sessions[session_id] = {
            'user_id': user_id,
            'payload': serialized,
            'mac': mac,
            'created_at': time.time()
        }
        return session_id

    def load_session(self, session_id: str) -> dict:
        """Load and deserialize session data."""
        if session_id not in self._sessions:
            raise KeyError("Session not found")

        session = self._sessions[session_id]

        # Verify integrity before deserializing
        if not verify_mac(session['payload'], session['mac']):
            raise ValueError("Session integrity check failed")

        return safe_deserialize(session['payload'])

    def import_session(self, session_id: str, payload: bytes, mac: str, user_id: str):
        """Import a session from an external source (e.g., migration).

        Used during cluster migration to transfer sessions between nodes.
        Validates HMAC before storing.
        """
        if not verify_mac(payload, mac):
            raise ValueError("Invalid MAC for imported session")

        # Verify the payload can be safely deserialized
        _ = safe_deserialize(payload)

        self._sessions[session_id] = {
            'user_id': user_id,
            'payload': payload,
            'mac': mac,
            'created_at': time.time()
        }


class CacheLayer:
    """Application cache with pickle-based serialization."""

    def __init__(self, max_size: int = 1000):
        self._cache = {}
        self._max_size = max_size
        self._access_times = {}

    def get(self, key: str) -> object:
        """Retrieve and deserialize a cached value."""
        if key not in self._cache:
            return None

        entry = self._cache[key]
        if time.time() - entry['stored_at'] > entry['ttl']:
            del self._cache[key]
            return None

        self._access_times[key] = time.time()
        return safe_deserialize(entry['data'])

    def put(self, key: str, value: object, ttl: int = 3600):
        """Serialize and cache a value."""
        if len(self._cache) >= self._max_size:
            self._evict()

        self._cache[key] = {
            'data': safe_serialize(value),
            'stored_at': time.time(),
            'ttl': ttl
        }
        self._access_times[key] = time.time()

    def _evict(self):
        """Evict least recently accessed entry."""
        if not self._access_times:
            return
        oldest_key = min(self._access_times, key=self._access_times.get)
        del self._cache[oldest_key]
        del self._access_times[oldest_key]

    def bulk_import(self, entries: list):
        """Import multiple cache entries from external source.

        Used for cache warming from a peer node. Each entry contains
        pre-serialized data that has already been validated by the peer.
        """
        for entry in entries:
            key = entry['key']
            raw_data = entry['data']  # base64-decoded bytes
            ttl = entry.get('ttl', 3600)

            # Validate by attempting deserialization with restricted unpickler
            _ = safe_deserialize(raw_data)

            self._cache[key] = {
                'data': raw_data,
                'stored_at': time.time(),
                'ttl': ttl
            }
            self._access_times[key] = time.time()


class RequestHandler(BaseHTTPRequestHandler):
    """HTTP handler for the cache/session service."""

    store = SessionStore()
    cache = CacheLayer()

    def do_POST(self):
        content_length = int(self.headers.get('Content-Length', 0))
        if content_length > 1048576:  # 1MB limit
            self.send_error(413)
            return

        body = self.rfile.read(content_length)

        try:
            request = json.loads(body)
        except json.JSONDecodeError:
            self.send_error(400, "Invalid JSON")
            return

        path = self.path

        if path == '/cache/import':
            self._handle_cache_import(request)
        elif path == '/session/create':
            self._handle_session_create(request)
        elif path == '/session/load':
            self._handle_session_load(request)
        else:
            self.send_error(404)

    def _handle_cache_import(self, request):
        """Handle bulk cache import from peer nodes."""
        import base64

        entries = request.get('entries', [])
        if not isinstance(entries, list) or len(entries) > 100:
            self.send_error(400, "Invalid entries")
            return

        decoded_entries = []
        for entry in entries:
            if not isinstance(entry, dict):
                continue
            key = entry.get('key', '')
            if not re.match(r'^[a-zA-Z0-9_:.-]{1,128}$', key):
                continue

            data_b64 = entry.get('data', '')
            try:
                raw_data = base64.b64decode(data_b64)
            except Exception:
                continue

            if len(raw_data) > 65536:
                continue

            decoded_entries.append({
                'key': key,
                'data': raw_data,
                'ttl': min(int(entry.get('ttl', 3600)), 86400)
            })

        try:
            self.cache.bulk_import(decoded_entries)
            self._send_json({'status': 'ok', 'imported': len(decoded_entries)})
        except Exception as e:
            self.send_error(500, str(e))

    def _handle_session_create(self, request):
        user_id = request.get('user_id', '')
        if not re.match(r'^[a-zA-Z0-9_-]{1,64}$', user_id):
            self.send_error(400, "Invalid user_id")
            return

        data = request.get('data', {})
        if not isinstance(data, dict):
            self.send_error(400, "Data must be a dict")
            return

        session_id = self.store.create_session(user_id, data)
        self._send_json({'session_id': session_id})

    def _handle_session_load(self, request):
        session_id = request.get('session_id', '')
        if not re.match(r'^[a-f0-9]{32}$', session_id):
            self.send_error(400, "Invalid session_id")
            return

        try:
            data = self.store.load_session(session_id)
            self._send_json({'data': str(data)})
        except (KeyError, ValueError) as e:
            self.send_error(404, str(e))

    def _send_json(self, obj):
        response = json.dumps(obj).encode()
        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(response)))
        self.end_headers()
        self.wfile.write(response)


if __name__ == '__main__':
    server = HTTPServer(('127.0.0.1', 8080), RequestHandler)
    print("Starting secure cache/session service on :8080")
    server.serve_forever()
